<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import AdminIntegrity from './AdminIntegrity.vue';
import {ArrowLeft,ClipboardList,Download,Search,ShieldCheck,ChevronLeft,ChevronRight,RefreshCw} from '@lucide/vue';
const props=defineProps<{request:(path:string,body?:object)=>Promise<any>}>();
const emit=defineEmits<{close:[];expired:[]}>();
interface Row{user_id:string;username:string;id:string;title:string;updated_at:string;status_label:string;task_count:number;executed_count:number;debit_minor:number;credit_minor:number}
interface Evidence{id:string;at:string;kind:string;title:string;description:string;task_id:string|null;approval_id:string|null;data:Record<string,any>}
interface Operation{id:string;task_id:string;title:string;status:string;status_label:string;amount_minor?:number;debit_minor:number;credit_minor:number;fields:{label:string;value:string}[];receipt:Record<string,any>|null;settlement:string;warnings:string[];ledger:{id:string;account_id:string;direction:string;amount_minor:number;category:string;occurred_at:string}[]}
interface Detail{user:{id:string;username:string};conversation:{id:string;title:string;created_at:string};summary:{task_count:number;operation_count:number;executed_count:number;pending_count:number;debit_minor:number;credit_minor:number};tasks:{id:string;status_label:string;error?:string;dag:{nodes:{id:string;title:string;status:string;depends_on:string[];started_at?:string;finished_at?:string;carried_from_task?:string}[]}}[];operations:Operation[];timeline:Evidence[];note:string}
const users=ref<{id:string;username:string}[]>([]),rows=ref<Row[]>([]),total=ref(0),offset=ref(0),userId=ref(''),query=ref(''),status=ref(''),from=ref(''),to=ref(''),selected=ref<Row|null>(null),detail=ref<Detail|null>(null),error=ref(''),loading=ref(false),opening=ref(false),exporting=ref(false),mode=ref('conversation'),safety=ref<Record<string,any>[]>([]),administrators=ref<Record<string,any>[]>([]);
let listVersion=0,detailVersion=0,recordsVersion=0;
const page=computed(()=>Math.floor(offset.value/50)+1),pages=computed(()=>Math.max(1,Math.ceil(total.value/50)));
const money=(value:number)=>'¥'+(value/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const time=(value:string)=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—';
const labels:Record<string,string>={request:'用户请求',task:'任务',step:'执行步骤',source:'后台依据',approval:'确认卡',receipt:'回执',ledger:'资金流水',verification:'身份验证',confirmation:'用户确认',control:'中断与恢复',error:'异常',security:'安全保护',human:'人工处理'};
const statuses:Record<string,string>={pending:'等待开始',running:'执行中',waiting_confirmation:'等待确认',succeeded:'已完成',failed:'失败',blocked:'后续已停止',cancelled:'已取消',uncertain:'结果待核查',needs_input:'等待补充信息'};
const evidenceLabels:Record<string,string>={schedule_id:'预约编号',authorization_id:'原授权操作编号',execute_at:'计划执行时间',decision:'用户选择',verification_required:'需要交易验证',level:'风险级别',sms_required:'需要短信验证',threshold_minor:'当时金额门槛',transaction_minor:'单笔金额',policy_version:'规则版本',basis:'统计口径',scope:'范围',account_id:'账户编号',tool:'业务工具',started_at:'开始时间',finished_at:'结束时间',receipt_id:'回执编号',action_id:'操作编号',status:'结果',title:'操作名称',executed_at:'执行时间',direction:'资金方向',amount_minor:'金额',category:'分类',counterparty:'交易对象',occurred_at:'记账时间',error:'异常原因',reason:'原因',risk_level:'风险级别',parent_task_id:'恢复前任务',saved_at:'保存时间',requested_at:'停止请求时间',stage:'停止位置',debit_minor:'已扣款',credit_minor:'已到账'};
function value(key:string,v:any):string{if(key.endsWith('_minor')&&typeof v==='number')return money(v);if(typeof v==='boolean')return v?'是':'否';if(v===null||v===undefined)return '—';return ({confirm:'确认',cancel:'取消',red:'红色',yellow:'黄色',single_transaction:'单笔交易',in:'入账',out:'扣款',executed:'成功'} as Record<string,string>)[String(v)]||String(v);}
function pairs(data:Record<string,any>){const flat={...data,...(data.assessment||{})};return Object.entries(flat).filter(([k,v])=>k in evidenceLabels&&(typeof v!=='object'||v===null)).map(([k,v])=>({label:evidenceLabels[k],value:value(k,v)}));}
async function load(reset=true){const version=++listVersion;if(reset){offset.value=0;selected.value=null;detail.value=null;detailVersion++;}loading.value=true;error.value='';const params=new URLSearchParams({offset:String(offset.value),limit:'50'});if(userId.value)params.set('user_id',userId.value);if(query.value.trim())params.set('query',query.value.trim());if(status.value)params.set('status',status.value);if(from.value)params.set('from_date',from.value);if(to.value)params.set('to_date',to.value);try{const result=await props.request('/audit/conversations?'+params);if(version!==listVersion)return;rows.value=result.items;total.value=result.total;users.value=result.users;}catch(e){if(version===listVersion)error.value=(e as Error).message;}finally{if(version===listVersion)loading.value=false;}}
function path(row:Row){return `/audit/users/${encodeURIComponent(row.user_id)}/conversations/${encodeURIComponent(row.id)}`;}
async function open(row:Row){const version=++detailVersion;selected.value=row;detail.value=null;opening.value=true;error.value='';try{const result=await props.request(path(row));if(version===detailVersion)detail.value=result;}catch(e){if(version===detailVersion)error.value=(e as Error).message;}finally{if(version===detailVersion)opening.value=false;}}
async function records(){const version=++recordsVersion,currentMode=mode.value,currentUser=userId.value;error.value='';loading.value=true;safety.value=[];administrators.value=[];try{if(currentMode==='security'){if(!currentUser)return;const result=await props.request(`/audit/users/${encodeURIComponent(currentUser)}/security`);if(version===recordsVersion&&mode.value===currentMode&&userId.value===currentUser)safety.value=result.items;}else if(currentMode==='admin'){const result=await props.request('/audit/administrators'+(currentUser?'?user_id='+encodeURIComponent(currentUser):''));if(version===recordsVersion&&mode.value===currentMode&&userId.value===currentUser)administrators.value=result.items;}}catch(e){if(version===recordsVersion)error.value=(e as Error).message;}finally{if(version===recordsVersion)loading.value=false;}}
async function switchMode(next:string){recordsVersion++;mode.value=next;if(next==='conversation')await load();else await records();}
async function filter(){if(mode.value==='conversation')await load();else await records();}
async function turn(delta:number){offset.value+=delta*50;await load(false);}
async function download(format:string){if(!selected.value||exporting.value)return;const target=selected.value;exporting.value=true;error.value='';try{const response=await fetch('/api/admin'+path(target)+'/export?format='+format,{credentials:'same-origin'});if(!response.ok){if(response.status===401)emit('expired');const data=await response.json();throw new Error(data.detail||'导出失败');}const blob=await response.blob();const href=URL.createObjectURL(blob);const link=document.createElement('a');link.href=href;link.download=`有数操作审计-${target.id}.${format}`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(href),1000);}catch(e){error.value=(e as Error).message;}finally{exporting.value=false;}}
onMounted(()=>load());
</script>

<template>
<section class="audit-workspace" aria-label="操作审计">
  <div class="audit-toolbar"><div class="audit-heading"><div><span class="audit-eyebrow">OPERATION AUDIT</span><h1><ClipboardList :size="21"/>操作审计</h1><p>沿着记录核对每一步，资金状态以已保存的回执与流水为准。</p></div><button @click="emit('close')"><ArrowLeft :size="15"/>返回客服</button></div>
    <nav class="audit-tabs" aria-label="审计分类"><button :class="{chosen:mode==='integrity'}" @click="switchMode('integrity')">防篡改校验</button><button :class="{chosen:mode==='conversation'}" @click="switchMode('conversation')">对话与交易</button><button :class="{chosen:mode==='security'}" @click="switchMode('security')">账户安全</button><button :class="{chosen:mode==='admin'}" @click="switchMode('admin')">管理员记录</button></nav>
    <form class="audit-filters" @submit.prevent="filter"><label>用户<select aria-label="用户" v-model="userId" @change="filter"><option value="">全部用户</option><option v-for="u in users" :key="u.id" :value="u.id">{{u.username}}</option></select></label><template v-if="mode==='conversation'"><label>对话标题<input aria-label="对话标题" v-model="query" maxlength="100" placeholder="例如：买入股票"/></label><label>最新任务状态<select aria-label="最新任务状态" v-model="status" @change="filter"><option value="">全部状态</option><option value="completed">已完成</option><option value="failed">失败</option><option value="waiting_confirmation">等待确认</option><option value="running">处理中</option><option value="queued">等待开始</option><option value="cancelled">已取消</option><option value="none">暂无任务</option></select></label><label>更新起始日期<input aria-label="更新起始日期" v-model="from" type="date"/></label><label>更新结束日期<input aria-label="更新结束日期" v-model="to" type="date"/></label></template><button class="primary" :disabled="loading"><Search :size="15"/>查询</button></form>
    <p v-if="error" class="audit-error" role="alert">{{error}}</p>
  </div>
  <div v-if="mode==='conversation'" class="audit-body" :class="{'audit-has-selection':!!selected}"><div class="audit-list"><div class="audit-list-header">{{loading?'正在读取…':`共 ${total} 段对话`}}</div><div class="audit-list-items"><button v-for="row in rows" :key="row.user_id+row.id" class="audit-row" :class="{chosen:selected?.id===row.id&&selected?.user_id===row.user_id}" @click="open(row)"><div><strong>{{row.username}}</strong><span>{{row.status_label}}</span></div><p>{{row.title}}</p><small>{{row.task_count}} 个任务 · {{row.executed_count}} 项已执行</small><small>{{time(row.updated_at)}}</small></button><p v-if="!loading&&!rows.length" class="audit-empty">没有符合条件的对话</p></div><div class="audit-pagination"><button aria-label="上一页" :disabled="page<=1||loading" @click="turn(-1)"><ChevronLeft :size="15"/></button><span>{{page}} / {{pages}}</span><button aria-label="下一页" :disabled="page>=pages||loading" @click="turn(1)"><ChevronRight :size="15"/></button></div></div>
    <div class="audit-detail"><p v-if="opening" class="audit-empty">正在核对任务、回执与流水…</p><template v-else-if="detail"><div class="audit-detail-title"><div><button class="audit-mobile-back" @click="selected=null;detail=null"><ArrowLeft :size="14"/>对话列表</button><span class="audit-eyebrow">{{detail.user.username}}</span><h2>{{detail.conversation.title}}</h2><small>对话编号 {{detail.conversation.id}}</small></div><div class="audit-export"><button aria-label="刷新当前审计" @click="selected&&open(selected)"><RefreshCw :size="15"/></button><button :disabled="exporting" @click="download('csv')"><Download :size="14"/>CSV</button><button :disabled="exporting" @click="download('json')"><Download :size="14"/>JSON</button></div></div>
      <div class="audit-metrics"><div><span>已记账扣款</span><strong>{{money(detail.summary.debit_minor)}}</strong></div><div><span>已记账入账</span><strong>{{money(detail.summary.credit_minor)}}</strong></div><div><span>成功操作 / 待确认</span><strong>{{detail.summary.executed_count}} <small>/ {{detail.summary.pending_count}}</small></strong></div></div><p class="audit-note"><ShieldCheck :size="15"/>{{detail.note}}</p>
      <section class="audit-section"><h3>操作与资金核对</h3><p v-if="!detail.operations.length" class="audit-muted">这段对话没有生成变更确认卡。</p><details v-for="op in detail.operations" :key="op.id" class="audit-operation"><summary><span>{{op.title}}</span><span :class="['audit-status',op.status]">{{op.status_label}}</span><b v-if="typeof op.amount_minor==='number'">{{money(op.amount_minor)}}</b></summary><div class="audit-operation-body"><p class="audit-id">操作编号 {{op.id}}</p><dl><div v-for="(field,i) in op.fields" :key="i"><dt>{{field.label}}</dt><dd>{{field.value}}</dd></div></dl><p>实际扣款 {{money(op.debit_minor)}} · 实际入账 {{money(op.credit_minor)}}</p><p class="audit-muted">{{op.settlement}}</p><p v-for="warning in op.warnings" :key="warning" class="audit-error">{{warning}}</p><div v-if="op.ledger.length" class="audit-table-wrap"><table><thead><tr><th>时间</th><th>账户编号</th><th>方向</th><th>金额</th><th>分类</th></tr></thead><tbody><tr v-for="entry in op.ledger" :key="entry.id"><td>{{time(entry.occurred_at)}}</td><td>{{entry.account_id}}</td><td>{{entry.direction==='out'?'扣款':'入账'}}</td><td>{{money(entry.amount_minor)}}</td><td>{{entry.category}}</td></tr></tbody></table></div><p v-else class="audit-muted">没有该操作关联的记账流水。</p><p v-if="op.receipt" class="audit-muted">回执时间 {{time(op.receipt.executed_at)}}</p></div></details></section>
      <section class="audit-section"><h3>任务步骤与依赖</h3><details v-for="task in detail.tasks" :key="task.id" class="audit-task"><summary><span>{{task.status_label}}</span><code>{{task.id}}</code><small>{{task.dag.nodes.length}} 个步骤</small></summary><p v-if="task.error" class="audit-error">{{task.error}}</p><ol><li v-for="(node,i) in task.dag.nodes" :key="node.id"><div><strong>{{i+1}}. {{node.title}}<small v-if="node.carried_from_task"> · 沿用已完成步骤</small></strong><span>{{statuses[node.status]||node.status}}</span></div><small>{{time(node.started_at||'')}} → {{time(node.finished_at||'')}}</small><p v-if="node.depends_on.length">依赖步骤：{{node.depends_on.map(id=>task.dag.nodes.find(n=>n.id===id)?.title||id).join('、')}}</p></li></ol><p v-if="!task.dag.nodes.length" class="audit-muted">该任务没有保存显式步骤，可能来自人工服务或直接操作。</p></details></section>
      <section class="audit-section"><h3>决策与执行时间线 <small>{{detail.timeline.length}} 条</small></h3><ol class="audit-timeline"><li v-for="item in detail.timeline" :key="item.id"><div class="audit-time"><time>{{time(item.at)}}</time><span>{{labels[item.kind]||item.kind}}</span></div><h4>{{item.title}}</h4><p v-if="item.description">{{item.description}}</p><details v-if="Object.keys(item.data).length" class="audit-evidence"><summary>查看依据</summary><dl><div v-for="(field,i) in pairs(item.data)" :key="i"><dt>{{field.label}}</dt><dd>{{field.value}}</dd></div></dl><dl v-if="item.data.fields"><div v-for="(field,i) in item.data.fields" :key="i"><dt>{{field.label}}</dt><dd>{{field.value}}</dd></div></dl><template v-if="item.data.display"><h5>{{item.data.display.title}}</h5><dl><div v-for="(metric,i) in item.data.display.metrics" :key="i"><dt>{{metric.label}}</dt><dd>{{metric.value}}</dd></div></dl><div class="audit-table-wrap"><table><thead><tr><th v-for="(column,i) in item.data.display.columns" :key="i">{{column}}</th></tr></thead><tbody><tr v-for="(row,i) in item.data.display.rows" :key="i"><td v-for="(cell,j) in row" :key="j">{{cell}}</td></tr></tbody></table></div></template></details><small v-if="item.approval_id" class="audit-id">操作 {{item.approval_id}}</small></li></ol></section>
    </template><div v-else-if="!opening" class="audit-welcome"><ClipboardList :size="40"/><h2>选择一段对话开始核对</h2><p>查看请求、执行步骤、身份验证、回执及实际流水。<br/>审计查询不会执行交易或恢复中断任务。</p></div></div>
  </div>
  <AdminIntegrity v-else-if="mode==='integrity'" :request="request" :users="users" :user-id="userId"/>
  <div v-else class="audit-records"><template v-if="mode==='security'"><p class="audit-note">这些是所选用户最近 300 条账户级安全记录，可能来自不同对话；没有操作编号的事件不会归入某段对话。</p><p v-if="!userId" class="audit-empty">请选择一个用户查看安全记录。</p><article v-for="(record,i) in safety" :key="i"><time>{{time(record.created_at)}}</time><h3>{{record.title}}</h3><p>{{record.detail}}</p><small>{{record.scope==='transactions'?'交易安全':record.scope==='securities'?'证券平台':record.scope==='travel'?'旅行平台':'外卖平台'}}<template v-if="record.reference"> · {{record.reference}}</template></small></article></template><template v-else><p class="audit-note">最近 300 条管理员登录、人工处理、审核、查看及导出记录。</p><div class="audit-table-wrap"><table><thead><tr><th>时间</th><th>操作</th><th>用户编号</th><th>关联记录</th></tr></thead><tbody><tr v-for="(record,i) in administrators" :key="i"><td>{{time(record.created_at)}}</td><td>{{record.title}}</td><td>{{users.find(u=>u.id===record.user_id)?.username||record.user_id||'—'}}</td><td>{{record.target||'—'}}</td></tr></tbody></table></div></template></div>
</section>
</template>

<style scoped>
